#!/bin/bash
# 装置スプライト画像は GitHub 連携(push) がバイナリを扱えないため、ビルド時に生成する。
# マスター画像 (切り抜き済み PNG) を base64 で埋め込み、各 .imageset へ書き出す。
# ローカルに実ファイルがある場合はそのまま（冪等：同一内容で上書き）。
# 第3ゲート（ドット絵版）: 初期7機種の本体（ドット絵）。C1 可動部 mov1 はアセット残置のため生成対象に含むが、c1.json の layers が空なので表示はされない（design/integration-beta3-log.md）。
set -euo pipefail
cd "$(dirname "$0")/.."

mkdir -p "$(dirname "FabTycoon/Assets.xcassets/eq_c1_front_body.imageset/eq_c1_front_body.png")"
